// MaxEco Node A.2: Validation, Honeypot Check & Indian Phone Sanitization
const input = $input.first().json;
const body = input.body || input;

// 1. Bot Honeypot Check
if (body.honeypot && body.honeypot.trim().length > 0) {
  return [{
    json: {
      status: 'REJECTED_SPAM',
      reason: 'Honeypot field populated by automated bot',
      timestamp: new Date().toISOString()
    }
  }];
}

// 2. Phone Validation (Indian 10-digit format with optional +91)
const rawPhone = String(body.phone || '').trim();
const digits = rawPhone.replace(/[^0-9]/g, '');
const isValidPhone = (digits.length === 10) || (digits.length === 12 && digits.startsWith('91'));

if (!isValidPhone) {
  return [{
    json: {
      status: 'REJECTED_VALIDATION_ERROR',
      reason: 'Invalid Indian mobile number format. Expected 10 digits.',
      timestamp: new Date().toISOString()
    }
  }];
}

// 3. Name & Service Check
const name = String(body.name || '').trim();
if (name.length < 2) {
  return [{
    json: {
      status: 'REJECTED_VALIDATION_ERROR',
      reason: 'Name must be at least 2 characters.',
      timestamp: new Date().toISOString()
    }
  }];
}

const cleanPhone = digits.length === 10 ? ('+91 ' + digits) : ('+' + digits.slice(0, 2) + ' ' + digits.slice(2));
const newLeadId = 'LEAD-' + new Date().getFullYear() + '-' + Math.floor(1000 + Math.random() * 9000);

return [{
  json: {
    status: 'ACCEPTED',
    lead: {
      id: newLeadId,
      name: name,
      contactPerson: body.contactPerson || name,
      phone: cleanPhone,
      email: (body.email || '').trim().toLowerCase(),
      service: body.service || 'Solar Advisory / IT Services',
      source: body.source || 'Website Form',
      stage: 'New',
      receivedAt: new Date().toISOString(),
      nextFollowUpDate: new Date().toISOString().slice(0, 10),
      nextAction: 'Review technical requirement and make introductory contact',
      notes: body.message || 'Website intake submission'
    }
  }
}];

// MaxEco Node A.4: Queue Lead to Local Intake Storage & Trigger Founder Digest Notification
const fs = require('fs');
const path = require('path');

const item = $input.first().json;
const outPath = path.resolve(process.cwd(), 'automation/data/lead-intake-queue.json');

let queue = [];
if (fs.existsSync(outPath)) {
  try { queue = JSON.parse(fs.readFileSync(outPath, 'utf8')); } catch(e) { queue = []; }
}

queue.push(item.lead);
fs.writeFileSync(outPath, JSON.stringify(queue, null, 2), 'utf8');

return [{
  json: {
    status: 'QUEUED_FOR_FOUNDER_REVIEW',
    leadId: item.lead.id,
    service: item.lead.service,
    timestamp: new Date().toISOString()
  }
}];

// MaxEco Node A.5: Reject / Log Invalid Intake Attempt
const item = $input.first().json;
return [{
  json: {
    status: item.status,
    reason: item.reason,
    timestamp: item.timestamp
  }
}];
